/i> rating</span><span><b><?= (int)($supplier['product_count']??0) ?></b> products</span></div></div><div class="supplier-card-actions"><a class="button button-primary" href="<?= e(BASE_URL) ?>/b2b/request-quotation.php?supplier=<?= (int)$supplier['id'] ?>">Contact supplier</a><a href="<?= e(BASE_URL) ?>/shop/products.php?supplier=<?= (int)$supplier['id'] ?>">View products →</a></div></article><?php endforeach; ?></div><?php endif; ?></main>
